CREATE TABLE `alarm_landings` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`slug` text NOT NULL,
	`is_active` integer DEFAULT true NOT NULL,
	`sort_order` integer DEFAULT 0 NOT NULL,
	`nav_label` text NOT NULL,
	`meta_title` text NOT NULL,
	`meta_description` text NOT NULL,
	`h1` text NOT NULL,
	`overline` text,
	`lead` text NOT NULL,
	`offer_points` text DEFAULT '[]' NOT NULL,
	`price_title` text DEFAULT '' NOT NULL,
	`included_title` text DEFAULT '' NOT NULL,
	`included` text DEFAULT '[]' NOT NULL,
	`faq` text DEFAULT '[]' NOT NULL,
	`form_title` text DEFAULT '' NOT NULL,
	`form_hint` text DEFAULT '' NOT NULL,
	`submit_label` text DEFAULT '' NOT NULL,
	`teaser` text DEFAULT '' NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX `alarm_landings_slug_unique` ON `alarm_landings` (`slug`);--> statement-breakpoint
INSERT OR IGNORE INTO `alarm_landings` (`slug`,`is_active`,`sort_order`,`nav_label`,`meta_title`,`meta_description`,`h1`,`overline`,`lead`,`offer_points`,`price_title`,`included_title`,`included`,`faq`,`form_title`,`form_hint`,`submit_label`,`teaser`) VALUES
('avtozapusk',1,1,'Сигнализация с автозапуском','Сигнализация с автозапуском в Казани | Detailing Place','Установка сигнализации с автозапуском в Казани: прогрев с телефона, GSM и метка. Цены от прайса студии, подбор под модель. Запись на установку.','Сигнализация с автозапуском в Казани','Сезон автозапуска','Садитесь в прогретый автомобиль: подберём систему с автозапуском под вашу модель и установим её скрыто. Стоимость оборудования и работ согласуем до монтажа.','["Прогрев и управление с телефона","Подбор под марку, модель и коробку","Скрытый монтаж в студии"]','Цены на установку сигнализации с автозапуском','Что входит в установку','["Консультация и подбор системы под марку, модель и ваши задачи","Скрытая установка блоков и подключение к цифровой шине CAN/LIN","Настройка автозапуска, датчиков и приложения","Проверка всех функций и сдача автомобиля","Срок — в среднем 1 рабочий день, сложные охранные комплексы — до 2 дней"]','[{"question":"Сколько стоит сигнализация с автозапуском с установкой в Казани?","answer":"Комплект с автозапуском и GSM — от 25 000 ₽ с установкой, итоговая цена зависит от модели автомобиля и выбранного оборудования. Точную стоимость назовём после подбора."},{"question":"Нужно ли оставлять второй ключ для автозапуска?","answer":"На большинстве современных автомобилей второй ключ не нужен — обход иммобилайзера делается программно. Для вашей модели мастер уточнит при подборе."},{"question":"Можно ли запускать двигатель с телефона?","answer":"Да, системы с GSM-модулем позволяют завести и прогреть автомобиль из приложения."},{"question":"Сколько времени занимает установка?","answer":"В среднем 1 рабочий день. Сложные охранные комплексы — до 2 дней."}]','Подберём автозапуск для вашего автомобиля','Укажите автомобиль и телефон — мастер перезвонит в рабочее время и назовёт стоимость.','Узнать цену с установкой','Прогрев с телефона: подбор и установка автозапуска'),
('vybor-signalizacii',1,2,'Как выбрать сигнализацию','Подбор автосигнализации в Казани | Detailing Place','Подбор охранной системы для автомобиля в Казани: автозапуск, GSM, GPS, защита от угона. Сравним варианты под вашу модель и бюджет.','Подбор охранной системы для автомобиля в Казани','Подбор сигнализации','Нужны уведомления об ударе, контроль автомобиля со смартфона или дистанционный запуск? Расскажите, что важно именно вам, и мастер предложит подходящую комплектацию.','["Сравним варианты под вашу модель","Учтём штатную охрану автомобиля","Цену согласуем до монтажа"]','Стоимость комплектов','Как проходит подбор и установка','["Для стоянки рядом с домом обсудим базовую охрану и оповещения, для машины на удалённой парковке — связь через GSM","Если нужен контроль местоположения, уточним наличие GPS/ГЛОНАСС-модуля в комплекте","Сравним варианты с учётом штатной охраны вашего автомобиля","Стоимость оборудования и работ согласуем до монтажа","Срок — в среднем 1 рабочий день, сложные охранные комплексы — до 2 дней"]','[{"question":"Какую сигнализацию выбрать?","answer":"Выбор зависит от модели автомобиля, места стоянки и нужных функций: автозапуск, управление с телефона, GPS. Мастер предложит варианты после подбора."},{"question":"Слетит ли машина с дилерской гарантии?","answer":"Нет. Подключение идёт через CAN-модули, вмешательство в проводку минимально."},{"question":"Сколько стоит охранный комплекс?","answer":"Базовая защита — от 15 000 ₽, комплект с автозапуском и GSM — от 25 000 ₽, охранный комплекс от угона — от 45 000 ₽."}]','Подберём систему под вашу машину','Укажите автомобиль и телефон — мастер перезвонит в рабочее время и предложит комплектацию.','Запросить подбор','Какую охранную систему выбрать'),
('starline',1,3,'Сигнализация StarLine','Установка сигнализации StarLine в Казани | Detailing Place','Установка сигнализации StarLine в Казани: автозапуск, GSM, управление из приложения. Подбор модели под автомобиль, скрытый монтаж.','Установка сигнализации StarLine в Казани','StarLine','Подберём модель StarLine под ваш автомобиль и задачи: автозапуск, управление из приложения, метка. Монтаж скрытый, стоимость согласуем до установки.','["Автозапуск и управление с телефона","Подбор модели под автомобиль","Скрытый монтаж"]','Цены на установку StarLine','Что входит в установку','["Подбор модели StarLine под марку, модель и задачи","Скрытая установка блоков и подключение к цифровой шине CAN/LIN","Настройка автозапуска, метки и приложения","Проверка всех функций и сдача автомобиля","Срок — в среднем 1 рабочий день, сложные охранные комплексы — до 2 дней"]','[{"question":"Какую модель StarLine поставить?","answer":"Модель подбираем под автомобиль, бюджет и нужные функции. Мастер предложит варианты после подбора."},{"question":"Можно ли запускать двигатель с телефона?","answer":"Да, модели с GSM-модулем позволяют завести и прогреть автомобиль из приложения."},{"question":"Сколько времени занимает установка?","answer":"В среднем 1 рабочий день. Сложные охранные комплексы — до 2 дней."}]','Подберём StarLine для вашего автомобиля','Укажите автомобиль и телефон — мастер перезвонит в рабочее время и назовёт стоимость.','Узнать цену StarLine','StarLine с автозапуском'),
('pandora',1,4,'Сигнализация Pandora','Установка сигнализации Pandora в Казани | Detailing Place','Установка сигнализации Pandora в Казани: автозапуск, GSM, управление из приложения. Подбор модели под автомобиль, скрытый монтаж.','Установка сигнализации Pandora в Казани','Pandora','Подберём модель Pandora под ваш автомобиль и задачи: автозапуск, управление из приложения, защита от угона. Монтаж скрытый, стоимость согласуем до установки.','["Автозапуск и управление с телефона","Подбор модели под автомобиль","Скрытый монтаж"]','Цены на установку Pandora','Что входит в установку','["Подбор модели Pandora под марку, модель и задачи","Скрытая установка блоков и подключение к цифровой шине CAN/LIN","Настройка автозапуска, датчиков и приложения","Проверка всех функций и сдача автомобиля","Срок — в среднем 1 рабочий день, сложные охранные комплексы — до 2 дней"]','[{"question":"Какую модель Pandora поставить?","answer":"Модель подбираем под автомобиль, бюджет и нужные функции. Мастер предложит варианты после подбора."},{"question":"Можно ли запускать двигатель с телефона?","answer":"Да, модели с GSM-модулем позволяют завести и прогреть автомобиль из приложения."},{"question":"Сколько времени занимает установка?","answer":"В среднем 1 рабочий день. Сложные охранные комплексы — до 2 дней."}]','Подберём Pandora для вашего автомобиля','Укажите автомобиль и телефон — мастер перезвонит в рабочее время и назовёт стоимость.','Узнать цену Pandora','Pandora с автозапуском');
